const respondTradeOffer = `-- name: RespondTradeOffer :execrows
UPDATE trade_offers SET status = $1, responded_at = $2, respond_key = $3
WHERE id = $4 AND status = 'pending'
`

type RespondTradeOfferParams struct {
	Status      string      `json:"status"`
	RespondedAt *time.Time  `json:"responded_at"`
	RespondKey  pgtype.Text `json:"respond_key"`
	ID          uuid.UUID   `json:"id"`
}

// decline / cancel / expire (accept uses AcceptTradeOffer).
func (q *Queries) RespondTradeOffer(ctx context.Context, arg RespondTradeOfferParams) (int64, error) {
	result, err := q.db.Exec(ctx, respondTradeOffer,
		arg.Status,
		arg.RespondedAt,
		arg.RespondKey,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const tradeDaoLuBonded = `-- name: TradeDaoLuBonded :one
SELECT EXISTS (
    SELECT 1 FROM dao_lu_members a JOIN dao_lu_members b ON b.bond_id = a.bond_id AND b.active
    WHERE a.character_id = $1 AND a.active AND b.character_id = $2
)::BOOLEAN AS bonded
`

type TradeDaoLuBondedParams struct {
	A uuid.UUID `json:"a"`
	B uuid.UUID `json:"b"`
}

// Are the two characters each other's active đạo lữ?
func (q *Queries) TradeDaoLuBonded(ctx context.Context, arg TradeDaoLuBondedParams) (bool, error) {
	row := q.db.QueryRow(ctx, tradeDaoLuBonded, arg.A, arg.B)
	var bonded bool
	err := row.Scan(&bonded)
	return bonded, err
}

const tradeFunnels = `-- name: TradeFunnels :many
WITH flows AS (
    SELECT t.receiver_character_id AS to_char, t.sender_character_id AS from_char, t.value_to_receiver AS v
    FROM trade_offers t WHERE t.status = 'accepted' AND t.responded_at >= $3 AND t.value_to_receiver > 0
    UNION ALL
    SELECT t2.sender_character_id, t2.receiver_character_id, t2.value_to_sender
    FROM trade_offers t2 WHERE t2.status = 'accepted' AND t2.responded_at >= $3 AND t2.value_to_sender > 0
)
SELECT flows.to_char AS character_id, c.name, count(DISTINCT flows.from_char)::INT AS distinct_senders,
       sum(flows.v)::BIGINT AS received, count(*)::INT AS trades
FROM flows JOIN characters c ON c.id = flows.to_char
GROUP BY flows.to_char, c.name
HAVING count(DISTINCT flows.from_char) >= $1::INT
ORDER BY distinct_senders DESC, received DESC, flows.to_char
LIMIT $2
`

type TradeFunnelsParams struct {
	MinSenders int32      `json:"min_senders"`
	Lim        int32      `json:"lim"`
	Since      *time.Time `json:"since"`
}

type TradeFunnelsRow struct {
	CharacterID     uuid.UUID `json:"character_id"`
	Name            string    `json:"name"`
	DistinctSenders int32     `json:"distinct_senders"`
	Received        int64     `json:"received"`
	Trades          int32     `json:"trades"`
}

// Many-to-one: receivers fed by ≥ @min_senders distinct characters.
func (q *Queries) TradeFunnels(ctx context.Context, arg TradeFunnelsParams) ([]TradeFunnelsRow, error) {
	rows, err := q.db.Query(ctx, tradeFunnels, arg.MinSenders, arg.Lim, arg.Since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TradeFunnelsRow{}
	for rows.Next() {
		var i TradeFunnelsRow
		if err := rows.Scan(
			&i.CharacterID,
			&i.Name,
			&i.DistinctSenders,
			&i.Received,
			&i.Trades,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const tradeLopsidedPairs = `-- name: TradeLopsidedPairs :many
WITH flows AS (
    SELECT t.sender_character_id AS from_char, t.receiver_character_id AS to_char, t.value_to_receiver AS v
    FROM trade_offers t WHERE t.status = 'accepted' AND t.responded_at >= $4 AND t.value_to_receiver > 0
    UNION ALL
    SELECT t2.receiver_character_id, t2.sender_character_id, t2.value_to_sender
    FROM trade_offers t2 WHERE t2.status = 'accepted' AND t2.responded_at >= $4 AND t2.value_to_sender > 0
), pr AS (
    SELECT LEAST(from_char, to_char)::uuid AS a, GREATEST(from_char, to_char)::uuid AS b,
           COALESCE(sum(v) FILTER (WHERE from_char < to_char), 0)::BIGINT AS a_to_b,
           COALESCE(sum(v) FILTER (WHERE from_char > to_char), 0)::BIGINT AS b_to_a,
           count(*)::INT AS trades
    FROM flows GROUP BY 1, 2
), px AS (
    SELECT pr.a, pr.b, pr.a_to_b, pr.b_to_a, pr.trades, (pr.a_to_b + pr.b_to_a) AS total,
           (GREATEST(pr.a_to_b, pr.b_to_a) * 10000 / GREATEST(pr.a_to_b + pr.b_to_a, 1))::BIGINT AS major_bp FROM pr
)
SELECT px.a, ca.name AS a_name, px.b, cb.name AS b_name, px.a_to_b, px.b_to_a, px.trades
FROM px JOIN characters ca ON ca.id = px.a JOIN characters cb ON cb.id = px.b
WHERE px.total >= $1::BIGINT AND px.major_bp >= $2::BIGINT
ORDER BY px.total DESC, px.a
LIMIT $3
`

type TradeLopsidedPairsParams struct {
	MinValue int64      `json:"min_value"`
	MinBp    int64      `json:"min_bp"`
	Lim      int32      `json:"lim"`
	Since    *time.Time `json:"since"`
}

type TradeLopsidedPairsRow struct {
	A      uuid.UUID `json:"a"`
	AName  string    `json:"a_name"`
	B      uuid.UUID `json:"b"`
	BName  string    `json:"b_name"`
	AToB   int64     `json:"a_to_b"`
	BToA   int64     `json:"b_to_a"`
	Trades int32     `json:"trades"`
}

// Pairs whose total value ≥ @min_value and whose larger direction is ≥ @min_bp of the total.
func (q *Queries) TradeLopsidedPairs(ctx context.Context, arg TradeLopsidedPairsParams) ([]TradeLopsidedPairsRow, error) {
	rows, err := q.db.Query(ctx, tradeLopsidedPairs,
		arg.MinValue,
		arg.MinBp,
		arg.Lim,
		arg.Since,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TradeLopsidedPairsRow{}
	for rows.Next() {
		var i TradeLopsidedPairsRow
		if err := rows.Scan(
			&i.A,
			&i.AName,
			&i.B,
			&i.BName,
			&i.AToB,
			&i.BToA,
			&i.Trades,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const tradeTopNetReceivers = `-- name: TradeTopNetReceivers :many

WITH flows AS (
    SELECT t.receiver_character_id AS to_char, t.sender_character_id AS from_char, t.value_to_receiver AS v
    FROM trade_offers t WHERE t.status = 'accepted' AND t.responded_at >= $2 AND t.value_to_receiver > 0
    UNION ALL
    SELECT t2.sender_character_id, t2.receiver_character_id, t2.value_to_sender
    FROM trade_offers t2 WHERE t2.status = 'accepted' AND t2.responded_at >= $2 AND t2.value_to_sender > 0
), per AS (
    SELECT to_char AS character_id, v AS received, 0::BIGINT AS sent, from_char AS peer, 1 AS n_in FROM flows
    UNION ALL
    SELECT from_char, 0::BIGINT, v, NULL::uuid, 0 FROM flows
)
SELECT per.character_id, c.name, sum(per.received)::BIGINT AS received, sum(per.sent)::BIGINT AS sent,
       (sum(per.received) - sum(per.sent))::BIGINT AS net, count(DISTINCT per.peer)::INT AS distinct_senders,
       sum(per.n_in)::INT AS trades_in
FROM per JOIN characters c ON c.id = per.character_id
GROUP BY per.character_id, c.name
HAVING sum(per.received) - sum(per.sent) > 0
ORDER BY net DESC, per.character_id
LIMIT $1
`

type TradeTopNetReceiversParams struct {
	Lim   int32      `json:"lim"`
	Since *time.Time `json:"since"`
}

type TradeTopNetReceiversRow struct {
	CharacterID     uuid.UUID `json:"character_id"`
	Name            string    `json:"name"`
	Received        int64     `json:"received"`
	Sent            int64     `json:"sent"`
	Net             int64     `json:"net"`
	DistinctSenders int32     `json:"distinct_senders"`
	TradesIn        int32     `json:"trades_in"`
}

// ───── admin: abnormal one-way flows (accepted trades since @since, stone-equivalent values) ─────
func (q *Queries) TradeTopNetReceivers(ctx context.Context, arg TradeTopNetReceiversParams) ([]TradeTopNetReceiversRow, error) {
	rows, err := q.db.Query(ctx, tradeTopNetReceivers, arg.Lim, arg.Since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TradeTopNetReceiversRow{}
	for rows.Next() {
		var i TradeTopNetReceiversRow
		if err := rows.Scan(
			&i.CharacterID,
			&i.Name,
			&i.Received,
			&i.Sent,
			&i.Net,
			&i.DistinctSenders,
			&i.TradesIn,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

